begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();

insert into auth.users(id,email) values
 ('95000000-0000-0000-0000-000000000001','write-a@test.dev'),
 ('95000000-0000-0000-0000-000000000002','write-b@test.dev');
insert into public.products(user_id,url,name,brand,price,image_url)
 select '95000000-0000-0000-0000-000000000001','https://write.test/'||n,'상품'||n,'원본 브랜드',null,'https://write.test/image.png' from generate_series(1,5) n;
insert into public.products(user_id,url,name) values ('95000000-0000-0000-0000-000000000002','https://write.test/other','다른 사람 상품');
select set_config('test.products',(select array_agg(id order by id)::text from public.products where user_id='95000000-0000-0000-0000-000000000001'),true);
select set_config('test.other',(select id::text from public.products where user_id='95000000-0000-0000-0000-000000000002'),true);

set local role anon;
select throws_ok($$select public.agree_community_policy()$$,'42501',null,'비회원 동의 차단');
select throws_ok($$select public.create_post('post','작성하는 본문',array[1::bigint],gen_random_uuid())$$,'42501',null,'비회원 등록 차단');
select throws_ok($$select public.delete_community_post(1)$$,'42501',null,'비회원 삭제 차단');
set local role authenticated;
select throws_ok($$select public.agree_community_policy()$$,'42501','not_authenticated','JWT 없는 동의 차단');
set local request.jwt.claims = '{"sub":"95000000-0000-0000-0000-000000000001","role":"authenticated"}';
select throws_ok($$select public.create_post('post','동의 이전 본문',(current_setting('test.products')::bigint[])[1:1],gen_random_uuid())$$,'42501','community_policy_required','일반글은 최초 동의 필요');
select lives_ok($$select public.agree_community_policy()$$,'동의 시각을 서버에 저장');
select set_config('test.agreed',(select community_policy_agreed_at::text from public.profiles),true);
select ok(current_setting('test.agreed')::timestamptz=now(),'동의 시각은 서버 현재 시각');
select is(public.agree_community_policy()::text,current_setting('test.agreed'),'반복 동의는 최초 시각 보존');
select throws_ok($$update public.profiles set community_policy_agreed_at=null$$,'42501',null,'직접 동의 변경 불가');
select throws_ok($$select public.create_post('post','네글자요',(current_setting('test.products')::bigint[])[1:1],gen_random_uuid())$$,'22023','invalid_post_content','최소 5자 서버 검사');
select throws_ok($$select public.create_post('post',repeat('가',51),(current_setting('test.products')::bigint[])[1:1],gen_random_uuid())$$,'22023','invalid_post_content','51자 서버 거부');
select throws_ok($$select public.create_post('post',E' \n\t   ',(current_setting('test.products')::bigint[])[1:1],gen_random_uuid())$$,'22023','invalid_post_content','공백 본문 거부');
select throws_ok($$select public.create_post('post',U&'가나 다라',(current_setting('test.products')::bigint[])[1:1],gen_random_uuid())$$,'22023','invalid_post_content','NBSP도 공백으로 제외');
select throws_ok($$select public.create_post('post',null,(current_setting('test.products')::bigint[])[1:1],gen_random_uuid())$$,'22023','invalid_post_content','null 본문 거부');
select throws_ok($$select public.create_post('post','정상적인 본문','{}'::bigint[],gen_random_uuid())$$,'22023','invalid_post_products','상품 0개 거부');
select throws_ok($$select public.create_post('post','정상적인 본문',current_setting('test.products')::bigint[],gen_random_uuid())$$,'22023','invalid_post_products','상품 5개 거부');
select throws_ok($$select public.create_post('vote','정상적인 본문',(current_setting('test.products')::bigint[])[1:2],gen_random_uuid())$$,'22023','invalid_post_products','투표 2개 거부');
select throws_ok($$select public.create_post('post','정상적인 본문',array[current_setting('test.other')::bigint],gen_random_uuid())$$,'22023','invalid_post_products','남의 상품 첨부 거부');
select throws_ok($$select public.create_post('post','정상적인 본문',array[999999999::bigint],gen_random_uuid())$$,'22023','invalid_post_products','없는 상품 첨부 거부');
select throws_ok($$select public.create_post('post','정상적인 본문',array[(current_setting('test.products')::bigint[])[1],(current_setting('test.products')::bigint[])[1]],gen_random_uuid())$$,'22023','invalid_post_products','중복 상품 거부');
select throws_ok($$select public.create_post('post','정상적인 본문',array[null::bigint],gen_random_uuid())$$,'22023','invalid_post_products','null 상품 거부');
select throws_ok($$select public.create_post('post','정상적인 본문',(current_setting('test.products')::bigint[])[1:1],null)$$,'22023','invalid_request_id','재시도 키 필수');
reset role;
select is((select count(*) from private.posts),0::bigint,'실패한 등록은 글이나 Snapshot을 남기지 않음');
select is((select count(*) from private.post_products),0::bigint,'검증 실패 시 Snapshot도 없음');
set local role authenticated;
select set_config('test.post',public.create_post('post','가 나 다 라 👨‍👩‍👧‍👦',(current_setting('test.products')::bigint[])[1:4],'95000000-0000-0000-0000-000000000011'),true);
select is(public.create_post('post','가 나 다 라 👨‍👩‍👧‍👦',(current_setting('test.products')::bigint[])[1:4],'95000000-0000-0000-0000-000000000011'),current_setting('test.post'),'응답 유실 재시도는 동일 글 id');
reset role;
select is((select count(*) from private.posts),1::bigint,'재시도로 중복 글 없음');
select is((select count(*) from private.post_products where post_id=current_setting('test.post')::bigint),4::bigint,'게시글 Snapshot 4개 원자적 생성');
select is((select name from private.post_products where post_id=current_setting('test.post')::bigint and position=1),'상품1','선택 순서 보존');
select is((select price from private.post_products where post_id=current_setting('test.post')::bigint and position=1),null,'가격 null 보존');
update public.products set name='바꾼 상품명',brand='바꾼 브랜드' where id=(current_setting('test.products')::bigint[])[1];
delete from public.products where id=(current_setting('test.products')::bigint[])[2];
select is((select name from private.post_products where post_id=current_setting('test.post')::bigint and position=1),'상품1','원본 수정 후 Snapshot 유지');
select is((select count(*) from private.post_products where post_id=current_setting('test.post')::bigint),4::bigint,'원본 삭제 후 Snapshot 유지');
set local role authenticated;
select lives_ok($$select public.create_post('post',repeat('👍🏽',50),(current_setting('test.products')::bigint[])[3:3],gen_random_uuid())$$,'피부색 이모지 50자 허용');
select set_config('test.vote',public.create_post('vote','정상 투표 본문',(current_setting('test.products')::bigint[])[3:3],gen_random_uuid()),true);
reset role;
select is((select ends_at-created_at from private.posts where id=current_setting('test.vote')::bigint),interval '24 hours','투표 종료 서버 생성 시각+24시간');
insert into private.comments(post_id,author_id,content) values (current_setting('test.vote')::bigint,'95000000-0000-0000-0000-000000000002','댓글');
insert into private.vote_responses(post_id,user_id,choice) values (current_setting('test.vote')::bigint,'95000000-0000-0000-0000-000000000002','buy');
set local request.jwt.claims = '{"sub":"95000000-0000-0000-0000-000000000002","role":"authenticated"}';
set local role authenticated;
select throws_ok($$select public.delete_community_post(current_setting('test.vote')::bigint)$$,'42501','post_not_found','남의 글 삭제 차단');
select lives_ok($$select public.create_post('vote','미동의 투표 본문',array[current_setting('test.other')::bigint],gen_random_uuid())$$,'최초 필수 동의는 일반글 진입에 적용');
reset role;
set local request.jwt.claims = '{"sub":"95000000-0000-0000-0000-000000000001","role":"authenticated"}';
update public.profiles set status='community_restricted',restricted_until=now()+interval '7 days' where id=auth.uid();
set local role authenticated;
select throws_ok($$select public.create_post('vote','제한 계정 본문',(current_setting('test.products')::bigint[])[3:3],gen_random_uuid())$$,'42501','community_restricted','제한 계정 신규 등록 차단');
select throws_ok($$select public.delete_community_post(current_setting('test.vote')::bigint)$$,'42501','community_restricted','제한 중 본인 글 삭제 차단');
reset role;
update public.profiles set restricted_until=now()-interval '1 second' where id=auth.uid();
set local role authenticated;
select lives_ok($$select public.delete_community_post(current_setting('test.vote')::bigint)$$,'제한 만료 후 본인 글 삭제 가능');
select lives_ok($$select public.delete_community_post(current_setting('test.vote')::bigint)$$,'삭제 재시도 안전');
reset role;
select ok((select deleted_at is not null from private.posts where id=current_setting('test.vote')::bigint),'글 soft delete');
select ok((select bool_and(deleted_at is not null) from private.comments where post_id=current_setting('test.vote')::bigint),'댓글 함께 soft delete');
select is((select count(*) from private.vote_responses where post_id=current_setting('test.vote')::bigint),0::bigint,'투표 응답 실제 삭제');
set local role authenticated;
select is(public.get_community_post(current_setting('test.vote')::bigint),null,'삭제 후 상세에서 제거');
select throws_ok($$select * from private.post_products$$,'42501',null,'Snapshot 직접 접근 차단');
select * from finish();
rollback;
